import{_ as o,o as r,c as l,ai as t}from"./chunks/framework.C33Uq6m-.js";const p=JSON.parse('{"title":"工具工坊","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/tool-workshop.md","filePath":"zh/guide/tool-workshop.md"}'),e={name:"zh/guide/tool-workshop.md"};function i(n,a,s,h,d,g){return r(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="工具工坊" tabindex="-1">工具工坊 <a class="header-anchor" href="#工具工坊" aria-label="Permalink to &quot;工具工坊&quot;">​</a></h1><p>工具工坊是一块可视化画布，用于构建、编辑和测试模型在对话中可以调用的工具定义。</p><p><strong>侧边栏位置：</strong> 工具工坊 <strong>路由：</strong> <code>/tools</code></p><h2 id="界面概览" tabindex="-1">界面概览 <a class="header-anchor" href="#界面概览" aria-label="Permalink to &quot;界面概览&quot;">​</a></h2><p>页面的核心是一块由 Vue Flow 驱动的<strong>节点式画布</strong>。每个工具表现为一个可视化节点，显示它的名称、描述、参数和实现代码。</p><h2 id="创建工具" tabindex="-1">创建工具 <a class="header-anchor" href="#创建工具" aria-label="Permalink to &quot;创建工具&quot;">​</a></h2><h3 id="从模板创建" tabindex="-1">从模板创建 <a class="header-anchor" href="#从模板创建" aria-label="Permalink to &quot;从模板创建&quot;">​</a></h3><p>点击<strong>模板</strong>可浏览 15 多个内置模板，包括：</p><ul><li>网页抓取（HTTP 请求）</li><li>计算器</li><li>Google 日历 / Gmail 集成</li><li>正则表达式测试</li><li>日期时间工具</li><li>以及更多</li></ul><h3 id="从零创建" tabindex="-1">从零创建 <a class="header-anchor" href="#从零创建" aria-label="Permalink to &quot;从零创建&quot;">​</a></h3><p>点击<strong>添加工具</strong>创建一个空白工具节点，然后填写：</p><ul><li><strong>名称</strong> —— 函数名（模型会用到）</li><li><strong>描述</strong> —— 这个工具做什么（帮助模型判断何时该调用它）</li><li><strong>参数</strong> —— 用 JSON Schema 定义的输入</li><li><strong>实现</strong> —— TypeScript 函数体</li></ul><h2 id="编辑工具" tabindex="-1">编辑工具 <a class="header-anchor" href="#编辑工具" aria-label="Permalink to &quot;编辑工具&quot;">​</a></h2><h3 id="行内代码编辑" tabindex="-1">行内代码编辑 <a class="header-anchor" href="#行内代码编辑" aria-label="Permalink to &quot;行内代码编辑&quot;">​</a></h3><p>每个工具节点都内嵌一个完整的 <strong>CodeMirror 6</strong> 编辑器，带 TypeScript 语法高亮。你可以直接在画布上修改实现。</p><h3 id="代码面板-双向同步" tabindex="-1">代码面板（双向同步） <a class="header-anchor" href="#代码面板-双向同步" aria-label="Permalink to &quot;代码面板（双向同步）&quot;">​</a></h3><p>打开<strong>代码面板</strong>，可以把所有工具看作一份合并的 TypeScript 源码。它使用 <strong>Recast AST 解析器</strong>实现双向同步：</p><ul><li>在面板中改代码 → 画布上的节点随之更新</li><li>在画布上改节点 → 面板中的代码随之更新</li></ul><h3 id="schema-查看器" tabindex="-1">Schema 查看器 <a class="header-anchor" href="#schema-查看器" aria-label="Permalink to &quot;Schema 查看器&quot;">​</a></h3><p>点击任意工具上的 schema 图标，可以查看自动生成的 <strong>OpenAI 兼容 JSON schema</strong>，并一键复制到其他系统使用。</p><h2 id="探测与选取" tabindex="-1">探测与选取 <a class="header-anchor" href="#探测与选取" aria-label="Permalink to &quot;探测与选取&quot;">​</a></h2><p>指向任意 API 地址即可：</p><ol><li><strong>探测</strong>接口 —— 发送请求并查看响应</li><li><strong>浏览 JSON 树</strong> —— 展开 / 折叠响应结构</li><li><strong>选取字段</strong> —— 挑出你需要的数据</li><li><strong>自动生成</strong>请求代码与参数映射</li></ol><h2 id="openapi-发现" tabindex="-1">OpenAPI 发现 <a class="header-anchor" href="#openapi-发现" aria-label="Permalink to &quot;OpenAPI 发现&quot;">​</a></h2><p>如果某个 API 有 OpenAPI/Swagger 规范：</p><ol><li>输入规范文件的 URL</li><li>LLMxRay 自动解析该规范</li><li>浏览可用的接口</li><li>选择一个接口，自动生成工具定义</li></ol><h2 id="实时执行" tabindex="-1">实时执行 <a class="header-anchor" href="#实时执行" aria-label="Permalink to &quot;实时执行&quot;">​</a></h2><p>对话过程中，当模型调用某个工具时：</p><ul><li>画布上对应的节点会<strong>脉动</strong>提示</li><li>执行结果以<strong>浮层</strong>形式出现在节点上</li><li>对话诊断中的工具调用时间线可以反向链接回画布</li></ul><h2 id="工具调用优化器" tabindex="-1">工具调用优化器 <a class="header-anchor" href="#工具调用优化器" aria-label="Permalink to &quot;工具调用优化器&quot;">​</a></h2><p>当模型在对话中调用工具后，结果上会出现一个**「优化此工具」**按钮。点击它会打开响应优化抽屉：</p><ol><li>把 API 响应<strong>可视化</strong>为交互式 JSON 树</li><li>只<strong>选取</strong>模型真正需要的字段</li><li><strong>自动生成</strong>带字段提取的优化版请求代码</li><li>一键在工坊中<strong>创建</strong>一个优化后的新工具</li></ol><h2 id="持久化" tabindex="-1">持久化 <a class="header-anchor" href="#持久化" aria-label="Permalink to &quot;持久化&quot;">​</a></h2><p>工具定义、节点位置、字段映射和探测配置都会被持久化保存，刷新浏览器也不会丢失。</p><h2 id="导出工具" tabindex="-1">导出工具 <a class="header-anchor" href="#导出工具" aria-label="Permalink to &quot;导出工具&quot;">​</a></h2><p>点击<strong>导出</strong>按钮，可把工具定义下载为 <strong>JSON</strong>。导出内容包含工具名称、描述、参数 schema 和实现代码 —— 重新导入或分享所需的一切。关于全部导出选项，详见<a href="./export.html">导出指南</a>。</p><h2 id="小贴士" tabindex="-1">小贴士 <a class="header-anchor" href="#小贴士" aria-label="Permalink to &quot;小贴士&quot;">​</a></h2><ul><li>从模板出发再做修改，比从零搭建快得多。</li><li>用 <strong>Schema 查看器</strong>确认你的工具定义符合模型的预期。</li><li><strong>探测与选取</strong>流程是把一个 REST API 包装成工具的最快方式。</li><li>启用后，工具会自动在对话中可用。</li></ul>',38)])])}const u=o(e,[["render",i]]);export{p as __pageData,u as default};
